import { HTMLAttributes } from 'react';

import GeoAlt from '@pohodnik/icons/svg/Geo/GeoAlt';
import Bezier2 from '@pohodnik/icons/svg/Graphics/Bezier2';

import { RouteObjectType } from '@apps/Routes/@types/routes.types';

interface IRouteObjectIconProps extends HTMLAttributes<HTMLSpanElement> {
  type: RouteObjectType;
  inDistance?: boolean;
  color?: string;
}

const RouteObjectIcon = ({
  type,
  inDistance = false,
  color = 'inherit',
  style = {},
  ...rest
}: IRouteObjectIconProps) => {
  return (
    <span
      {...rest}
      style={{
        color,
        fontSize: 18,
        opacity: inDistance ? 1 : 0.5,
        ...style,
      }}
    >
      {type === RouteObjectType.Point && <GeoAlt />}
      {type === RouteObjectType.Line && <Bezier2 />}
    </span>
  );
};

export default RouteObjectIcon;
